begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,auth,pg_catalog;
select plan(22);
select has_table('transport_orders'); select has_table('transport_stops'); select has_table('transport_items'); select has_table('transport_assignments'); select has_table('transport_events');
select enum_has_labels('public','transport_order_status',array['draft','planned','assigned','loading','in_transit','unloading','completed','cancelled','archived']);
