insert into transport_orders(id,organization_id,order_number,customer_id,transport_type,created_by) values('c0000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001','', 'bc000000-0000-4000-8000-000000000001','General','ba000000-0000-4000-8000-000000000001');
select is((select order_number from transport_orders where id='c0000000-0000-4000-8000-000000000001'),'TR-00000001','genera número monotónico');
insert into transport_orders(id,organization_id,order_number,customer_id,transport_type,created_by) values('c0000000-0000-4000-8000-000000000002','bb000000-0000-4000-8000-000000000001','', 'bc000000-0000-4000-8000-000000000001','Express','ba000000-0000-4000-8000-000000000001');
