select throws_ok($$update transport_orders set status='completed' where id='c0000000-0000-4000-8000-000000000001'$$,'23514',null,'rechaza salto de estado');
update transport_orders set planned_pickup_at='2026-09-01 08:00Z',planned_delivery_at='2026-09-01 12:00Z',status='planned' where id='c0000000-0000-4000-8000-000000000001';
select is((select status::text from transport_orders where id='c0000000-0000-4000-8000-000000000001'),'planned','acepta transición draft-planned');
