insert into transport_events(id,organization_id,transport_order_id,event_type,actor_user_id,entity_type,entity_id) values('c3000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001','c0000000-0000-4000-8000-000000000001','transport.created','ba000000-0000-4000-8000-000000000001','order','c0000000-0000-4000-8000-000000000001');
select throws_ok($$delete from transport_events where id='c3000000-0000-4000-8000-000000000001'$$,'55000',null,'eventos no se borran');
select is((select count(*)::integer from information_schema.role_table_grants where grantee='anon' and table_schema='public' and table_name like 'transport_%'),0,'anon sin grants');
select is((select count(*)::integer from pg_class where relnamespace='public'::regnamespace and relname in('transport_order_counters','transport_orders','transport_stops','transport_items','transport_assignments','transport_events') and relrowsecurity and relforcerowsecurity),6,'RLS forzada');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"ba000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is((select count(*)::integer from transport_orders),2,'admin solo lee órdenes de su tenant con módulo activo');
select throws_ok($$insert into transport_orders(organization_id,order_number,customer_id,transport_type,created_by) values('bb000000-0000-4000-8000-000000000001','','bc000000-0000-4000-8000-000000000001','General','ba000000-0000-4000-8000-000000000001')$$,'42501',null,'frontend no escribe directamente');
select set_config('request.jwt.claims','{"sub":"ba000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*)::integer from transport_orders),0,'tenant sin transport_management no accede por RLS');
reset role;
select * from finish();rollback;
